-- ORM-generated CRUD for a web application (users, orders, products)
SELECT `id`, `email`, `created_at` FROM `users` WHERE `id` = 42 LIMIT 1;
SELECT u.id, u.email FROM users AS u WHERE u.email = 'a@example.com' AND u.deleted_at IS NULL;
SELECT * FROM products WHERE category_id IN (1, 2, 3) AND price BETWEEN 10 AND 100 ORDER BY price DESC LIMIT 20 OFFSET 40;
SELECT * FROM products WHERE name LIKE '%widget%' ESCAPE '\\' OR sku LIKE 'WD-%';
INSERT INTO users (email, name, created_at) VALUES ('a@example.com', 'Alice', NOW());
INSERT INTO users (email, name) VALUES ('b@example.com', 'Bob'), ('c@example.com', 'Carol'), ('d@example.com', 'Dave');
INSERT INTO users SET email = 'e@example.com', name = 'Eve';
INSERT IGNORE INTO tags (name) VALUES ('go'), ('sql');
INSERT INTO page_views (page_id, views) VALUES (1, 1) ON DUPLICATE KEY UPDATE views = views + 1;
INSERT INTO users (email, name) SELECT email, name FROM staging_users WHERE imported = 0;
REPLACE INTO settings (k, v) VALUES ('theme', 'dark');
UPDATE users SET name = 'Alice B', updated_at = NOW() WHERE id = 1;
UPDATE products SET stock = stock - 1 WHERE id = 7 AND stock > 0;
UPDATE orders o JOIN users u ON u.id = o.user_id SET o.status = 'archived' WHERE u.deleted_at IS NOT NULL;
UPDATE products SET price = price * 1.1 WHERE category_id = 3 ORDER BY id LIMIT 100;
DELETE FROM sessions WHERE expires_at < NOW();
DELETE FROM carts WHERE user_id = 5 ORDER BY id LIMIT 10;
DELETE o FROM orders o LEFT JOIN users u ON u.id = o.user_id WHERE u.id IS NULL;
SELECT o.id, o.total, u.email FROM orders o INNER JOIN users u ON u.id = o.user_id WHERE o.status = 'paid';
SELECT o.id, i.product_id, i.qty FROM orders o LEFT JOIN order_items i ON i.order_id = o.id WHERE o.user_id = 3;
SELECT COUNT(*) FROM orders WHERE created_at >= '2025-01-01';
SELECT p.* FROM products p WHERE EXISTS (SELECT 1 FROM order_items i WHERE i.product_id = p.id);
SELECT * FROM users WHERE id NOT IN (SELECT user_id FROM bans);
SELECT id FROM users WHERE id = ? AND status = ?;
SELECT * FROM users WHERE (status, role) IN (('active', 'admin'), ('active', 'editor'));
SELECT * FROM orders WHERE user_id = 9 ORDER BY created_at DESC LIMIT 10 FOR UPDATE;
SELECT * FROM inventory WHERE sku = 'X1' LOCK IN SHARE MODE;
START TRANSACTION;
COMMIT;
SELECT LAST_INSERT_ID();
SELECT DATABASE(), VERSION(), CURRENT_USER();
SELECT IFNULL(nickname, name) AS display, COALESCE(phone, mobile, 'n/a') AS contact FROM users;
SELECT CASE WHEN total > 1000 THEN 'big' WHEN total > 100 THEN 'mid' ELSE 'small' END AS bucket FROM orders;
SELECT CONCAT(first_name, ' ', last_name) AS full_name, UPPER(email) FROM users;
SELECT DATE_FORMAT(created_at, '%Y-%m') AS ym, COUNT(*) FROM orders GROUP BY ym;
